package glitch

import data.glitch_lib

# Insecure protocols without TLS/SSL
insecure_protocols := {"http://", "ftp://", "telnet://", "smtp://", "ldap://", "tcp://"}

# Secure protocol indicators
secure_indicators := {"https", "ftps", "ldaps", "smtps", "tls", "ssl"}

# Encryption-related attribute names
encryption_attrs := {"enableHttpsTrafficOnly", "httpsOnly", "secureTransport", "sslRequired", "tlsRequired", "encryptionEnabled", "useSsl", "useTLS"}

# Inversion attributes that should be false when secure
inversion_attrs := {"insecure", "skipVerify", "allowInsecure", "noSSL", "disableTLS", "verifySsl", "sslVerify", "tlsVerify", "certificateValidation"}

# TLS version attributes
tls_version_attrs := {"minimumTlsVersion", "tlsVersion", "securityPolicy", "sslPolicy"}

# Deprecated TLS/SSL versions
deprecated_versions := {"TLSv1.0", "TLSv1.1", "SSLv3", "1.0", "1.1", "SSLv2", "2008", "2012"}

# Insecure ports
insecure_ports := {80, 21, 23, 25, 110, 143}

# Certificate-related attributes
cert_attrs := {"clientCertificateMode", "serverCertificate", "caCertificate", "clientCertificate"}

# Insecure certificate modes
insecure_cert_modes := {"None", "Optional", "OptionalNoClient", "none", "optional", "optionalnoclient"}

# Boolean false values indicating insecurity
insecure_booleans := {false, "false", 0, "no", "disabled", "off"}

# Helper to check if string starts with insecure protocol
has_insecure_protocol(str) {
    protocol := insecure_protocols[_]
    startswith(str, protocol)
}

# Check if string contains any secure indicator
has_secure_indicator(str) {
    indicator := secure_indicators[_]
    contains(lower(str), indicator)
}

# Extract string value from various node types
get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
} else = value {
    node.ir_type == "VariableReference"
    value := node.value
}

# Check if node represents false/disabled value
is_disabled_or_false(node) {
    node.ir_type == "Boolean"
    node.value == false
} else {
    node.ir_type == "String"
    node.value == "false"
} else {
    node.ir_type == "String"
    node.value == "disabled"
} else {
    node.ir_type == "String"
    node.value == "no"
} else {
    node.ir_type == "String"
    node.value == "off"
} else {
    node.ir_type == "Integer"
    node.value == 0
}

# Check if node represents insecure port number
is_insecure_port(node) {
    node.ir_type == "Integer"
    node.value == insecure_ports[_]
} else {
    node.ir_type == "String"
    to_number(node.value) == insecure_ports[_]
}

# Check if string contains deprecated TLS version
contains_deprecated_version(str) {
    version := deprecated_versions[_]
    contains(str, version)
}

# Rule 1: Unencrypted protocol specifications in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check common protocol-related attribute names
    attr.name in {"protocol", "scheme", "url", "endpoint", "address", "source", "destination", "upstream", "target"}

    str_val := get_string_value(attr.value)
    has_insecure_protocol(str_val)
    not has_secure_indicator(str_val)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted protocol detected in communication endpoint. (CWE-319)"
    }
}

# Rule 2: Disabled or absent encryption flags
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in encryption_attrs
    is_disabled_or_false(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption/security feature is explicitly disabled. (CWE-319)"
    }
}

# Rule 3: Explicit insecure configuration flags
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in inversion_attrs
    is_disabled_or_false(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Security verification or validation is disabled. (CWE-319)"
    }
}

# Rule 4: Deprecated TLS/SSL versions in security policies
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in tls_version_attrs

    str_val := get_string_value(attr.value)
    contains_deprecated_version(str_val)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Deprecated or insecure TLS/SSL version specified. (CWE-319)"
    }
}

# Rule 5: Insecure port configurations without secure redirection
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"port", "containerPort", "hostPort", "targetPort", "listenerPort", "bindPort", "servicePort"}
    is_insecure_port(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted port used without secure alternative. (CWE-319)"
    }
}

# Rule 6: Insecure certificate validation modes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in cert_attrs

    str_val := get_string_value(attr.value)
    lower(str_val) in {"none", "optional", "optionalnoclient"}

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Client certificate validation not required. (CWE-319)"
    }
}

# Rule 7: String literals with insecure URLs
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk all elements to find string values
    walk(parent, [_, element])
    element.ir_type == "String"

    has_insecure_protocol(element.value)
    not has_secure_indicator(element.value)

    # Avoid duplicates with attribute checks by ensuring this is a standalone string
    not is_part_of_secure_attribute(parent, element)

    result := {
        "type": "sec_https",
        "element": element,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - URL using unencrypted protocol detected. (CWE-319)"
    }
}

# Helper to check if string is part of a properly checked attribute
is_part_of_secure_attribute(parent, element) {
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]
    attr.value == element
    attr.name in {"protocol", "scheme", "url", "endpoint", "address", "source", "destination"}
}

# Rule 8: Absence of encryption when sensitive attributes present
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    # Check for sensitive data indicators
    has_sensitive_data_attr(attrs)

    # Check that encryption is not enabled
    not has_encryption_enabled(attrs)

    # Check for protocol indication that's insecure
    has_insecure_protocol_attr(attrs)

    attr := attrs[_]
    attr.name in {"password", "secret", "token", "credential", "key", "connectionString"}

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Sensitive data may be transmitted without encryption. (CWE-319)"
    }
}

# Helper: check if any attribute indicates sensitive data
has_sensitive_data_attr(attrs) {
    attr := attrs[_]
    attr.name in {"password", "secret", "token", "credential", "key", "certificate", "connectionString", "authToken", "apiKey"}
}

# Helper: check if encryption is enabled
has_encryption_enabled(attrs) {
    attr := attrs[_]
    attr.name in encryption_attrs
    not is_disabled_or_false(attr.value)
}

# Helper: check if there's an insecure protocol attribute
has_insecure_protocol_attr(attrs) {
    attr := attrs[_]
    attr.name in {"protocol", "scheme", "url", "endpoint"}
    str_val := get_string_value(attr.value)
    has_insecure_protocol(str_val)
}

